import test from 'node:test';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {spawnSync} from 'node:child_process';
import {mkdtempSync, mkdirSync, readFileSync, writeFileSync, rmSync} from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {verifyLocalFulfillment} from '../../scripts/verify-local-fulfillment.mjs';

test('fulfillment verifier hashes actual candidate bytes and rejects tampering, identity and path drift', (t) => {
  const root = mkdtempSync(path.join(os.tmpdir(), 'shpitto-vendor-verifier-'));
  t.after(() => rmSync(root, {recursive: true, force: true}));
  const candidateId = 'fixture-candidate';
  const directory = path.join(root, 'internal/evidence/m8/artifact-manifest', candidateId);
  mkdirSync(directory, {recursive: true});
  mkdirSync(path.join(root, 'vendor/sales'), {recursive: true});
  writeFileSync(path.join(root, 'vendor/sales/commerce.config.json'), readFileSync('vendor/sales/commerce.config.json', 'utf8'), 'utf8');
  const bytes = Buffer.from('fixture candidate bytes');
  const manifest = {candidateId, zip: {path: `internal/evidence/m8/artifact-manifest/${candidateId}/fixture.zip`, bytes: bytes.length, sha256: createHash('sha256').update(bytes).digest('hex')}};
  const save = (value) => writeFileSync(path.join(directory, 'manifest.json'), JSON.stringify(value), 'utf8');
  save(manifest);
  writeFileSync(path.join(directory, 'fixture.zip'), bytes);
  assert.equal(verifyLocalFulfillment(root, candidateId).status, 'PASS');
  writeFileSync(path.join(directory, 'fixture.zip'), 'changed', 'utf8');
  assert.throws(() => verifyLocalFulfillment(root, candidateId), /SHA-256 mismatch/);
  writeFileSync(path.join(directory, 'fixture.zip'), bytes);
  save({...manifest, zip: {...manifest.zip, bytes: 0}});
  assert.throws(() => verifyLocalFulfillment(root, candidateId), /byte length mismatch/);
  save({...manifest, candidateId: 'different'});
  assert.throws(() => verifyLocalFulfillment(root, candidateId), /identity/);
  save({...manifest, zip: {...manifest.zip, path: 'vendor/sales/commerce.config.json'}});
  assert.throws(() => verifyLocalFulfillment(root, candidateId), /inside/);
  assert.throws(() => verifyLocalFulfillment(root, '../other'), /safe path/);
  const execute = () => spawnSync(process.execPath, [path.resolve('scripts/verify-local-fulfillment.mjs')], {cwd: root, encoding: 'utf8', windowsHide: true, env: {...process.env, SHPITTO_CANDIDATE_ID: candidateId}});
  save(manifest);
  assert.equal(execute().status, 0);
  const evidence = path.join(root, 'internal/evidence/m8/fulfillment/local-fixture/result.json');
  assert.equal(JSON.parse(readFileSync(evidence, 'utf8')).status, 'PASS');
  writeFileSync(path.join(directory, 'fixture.zip'), 'corrupted', 'utf8');
  assert.equal(execute().status, 1);
  assert.equal(JSON.parse(readFileSync(evidence, 'utf8')).status, 'FAIL');
});
